PAYLOAD = json.loads('{"install_reference_extras.sh": "#!/bin/bash\\n# Preserve the known-working CUDA stacks; never install CPU JAX or replace PyTorch.\\nset -eo pipefail\\nGP_ROOT=\\"$(cd -- \\"$(dirname -- \\"${BASH_SOURCE[0]}\\")\\" && pwd)\\"\\nsource \\"$GP_ROOT/slurm/environment.sh\\"\\necho \'== GAD reference installer: numpy2-isolation-repair-2\'\\nGP_CONSTRAINTS=\\"$(mktemp)\\"\\ntrap \'rm -f \\"$GP_CONSTRAINTS\\"\' EXIT\\npython - \\"$GP_CONSTRAINTS\\" <<\'PY\'\\nimport importlib.metadata,sys\\nfrom pathlib import Path\\nnames=[\'jax\',\'jaxlib\',\'torch\',\'numpy\',\'scipy\',\'pandas\',\'matplotlib\',\'jax-cuda12-plugin\',\'jax-cuda12-pjrt\',\'jax-cuda13-plugin\',\'jax-cuda13-pjrt\']\\nrows=[]\\nfor name in names:\\n    try: rows.append(name+\'==\'+importlib.metadata.version(name))\\n    except importlib.metadata.PackageNotFoundError: pass\\nPath(sys.argv[1]).write_text(\'\\\\n\'.join(rows)+\'\\\\n\')\\nPY\\nGP_ISOLATE_DIAGNOSTICS=\\"$(python -c \'from arviz_compat import needs_isolated_arviz; print(int(needs_isolated_arviz()))\')\\"\\nif [[ \\"$GP_ISOLATE_DIAGNOSTICS\\" == 1 ]]; then\\n  echo \'== Keeping ArviZ out of the main environment; using isolated diagnostics.\'\\n  # ArviZ 0.17 requires NumPy <2; leave the working GPU environment untouched.\\n  python -m pip install -c \\"$GP_CONSTRAINTS\\" numpyro pypdf\\n  GP_DIAGNOSTICS_PYTHON=\\"$(python -c \'from arviz_compat import diagnostics_python; print(diagnostics_python())\')\\"\\n  GP_DIAGNOSTICS_VENV=\\"$(dirname -- \\"$(dirname -- \\"$GP_DIAGNOSTICS_PYTHON\\")\\")\\"\\n  if [[ ! -x \\"$GP_DIAGNOSTICS_PYTHON\\" ]]; then\\n    python -m venv \\"$GP_DIAGNOSTICS_VENV\\"\\n  fi\\n  \\"$GP_DIAGNOSTICS_PYTHON\\" -m pip install \'numpy==1.26.4\' \'scipy==1.13.1\' \'arviz==0.17.1\'\\n  export GP_DIAGNOSTICS_PYTHON\\nelse\\n  GP_ARVIZ_SPEC=\\"$(python -c \'import sys; print(\\"arviz==0.17.1\\" if sys.version_info < (3,10) else \\"arviz>=0.18,<1\\")\')\\"\\n  python -m pip install -c \\"$GP_CONSTRAINTS\\" numpyro \\"$GP_ARVIZ_SPEC\\" pypdf\\nfi\\npython \\"$GP_ROOT/check_environment.py\\" --imports-only\\n", "arviz_compat.py": "\\"\\"\\"Use native ArviZ or its isolated diagnostic environment on Python 3.9/NumPy 2.\\"\\"\\"\\nimport importlib.metadata\\nimport os\\nfrom pathlib import Path\\nimport subprocess\\nimport sys\\nimport tempfile\\nimport types\\n\\n\\ndef diagnostics_python():\\n    return Path(os.environ.get(\'GP_DIAGNOSTICS_PYTHON\') or\\n                (str(Path(sys.prefix))+\'_gad_diagnostics/bin/python\'))\\n\\n\\ndef needs_isolated_arviz():\\n    import numpy as np\\n    if sys.version_info>=(3,10):return False\\n    versions=[np.__version__]\\n    try:versions.append(importlib.metadata.version(\'numpy\'))\\n    except importlib.metadata.PackageNotFoundError:pass\\n    return any(int(v.split(\'.\')[0])>=2 for v in versions)\\n\\n\\nclass _Posterior:\\n    def __init__(self,posterior,python):\\n        import numpy as np\\n        self.arrays={k:np.asarray(v) for k,v in posterior.items()}\\n        self.python=python\\n        self.results=None\\n\\n    def metric(self,name,method):\\n        allowed={\'rhat\':{\'rank\'},\'ess\':{\'bulk\',\'tail\'},\'mcse\':{\'mean\'}}\\n        if method not in allowed.get(name,set()):raise ValueError(\'Unsupported diagnostic method\')\\n        if self.results is None:\\n            import numpy as np\\n            with tempfile.TemporaryDirectory(prefix=\'gad-arviz-\') as temporary:\\n                source=Path(temporary)/\'posterior.npz\';dest=Path(temporary)/\'diagnostics.npz\'\\n                np.savez(source,**self.arrays)\\n                result=subprocess.run([str(self.python),\'-I\',str(Path(__file__).with_name(\'diagnostics_worker.py\')),\\n                                       str(source),str(dest)],capture_output=True,text=True)\\n                if result.returncode:\\n                    raise RuntimeError(\'Isolated ArviZ diagnostics failed: \'+result.stderr.strip())\\n                with np.load(dest,allow_pickle=False) as data:\\n                    self.results={k:data[k].copy() for k in data.files}\\n        prefix=name+\'_\'+method+\'__\'\\n        return {k:types.SimpleNamespace(values=self.results[prefix+k]) for k in self.arrays}\\n\\n\\ndef _isolated_arviz():\\n    python=diagnostics_python()\\n    if not python.is_file():\\n        raise RuntimeError(\'Python 3.9 with NumPy 2 needs the isolated ArviZ environment. \'\\n                           \'Run bash install_reference_extras.sh; expected \'+str(python))\\n    module=types.ModuleType(\'arviz\')\\n    module.__version__=\'0.17.1 (isolated NumPy 1.26.4)\'\\n    module.from_dict=lambda *,posterior:_Posterior(posterior,python)\\n    module.rhat=lambda data,method=\'rank\':data.metric(\'rhat\',method)\\n    module.ess=lambda data,method=\'bulk\':data.metric(\'ess\',method)\\n    module.mcse=lambda data,method=\'mean\':data.metric(\'mcse\',method)\\n    module.__gad_isolated__=True\\n    return module\\n\\n\\ndef load_arviz():\\n    import numpy as np\\n    if needs_isolated_arviz():\\n        current=sys.modules.get(\'arviz\')\\n        if not getattr(current,\'__gad_isolated__\',False):sys.modules[\'arviz\']=_isolated_arviz()\\n        return sys.modules[\'arviz\']\\n    version=importlib.metadata.version(\'arviz\')\\n    if tuple(int(v) for v in version.split(\'.\')[:2]) < (0,18):\\n        # ArviZ 0.17 imports the old SciPy alias, removed in SciPy 1.13.\\n        # It is the very same Gaussian window function in its current module.\\n        import scipy.signal\\n        if not hasattr(scipy.signal,\'gaussian\'):\\n            scipy.signal.gaussian=scipy.signal.windows.gaussian\\n    import arviz\\n    return arviz\\n", "diagnostics_worker.py": "\\"\\"\\"Actual ArviZ calculations in the separate NumPy-1 environment; no GPU imports.\\"\\"\\"\\nimport sys\\nimport numpy as np\\nimport scipy.signal\\n\\nif not hasattr(scipy.signal,\'gaussian\'):\\n    scipy.signal.gaussian=scipy.signal.windows.gaussian\\nimport arviz as az\\n\\n\\ndef main():\\n    with np.load(sys.argv[1],allow_pickle=False) as data:\\n        posterior={k:data[k] for k in data.files}\\n    inference=az.from_dict(posterior=posterior)\\n    arrays={}\\n    for name,method in [(\'rhat\',\'rank\'),(\'ess\',\'bulk\'),(\'ess\',\'tail\'),(\'mcse\',\'mean\')]:\\n        result=getattr(az,name)(inference,method=method)\\n        for key in posterior:arrays[name+\'_\'+method+\'__\'+key]=np.asarray(result[key].values)\\n    np.savez(sys.argv[2],**arrays)\\n\\n\\nif __name__==\'__main__\':main()\\n", "check_environment.py": "\\"\\"\\"Exercise APIs, float64 PDE prerequisites, CUDA, and NUTS continuation before expensive jobs.\\"\\"\\"\\nimport argparse\\nimport importlib.metadata\\nimport os\\nimport platform\\nfrom pathlib import Path\\nfrom common import write_json\\n\\n\\ndef check(*, imports_only=False, allow_cpu=False, record=None):\\n    import numpy as np\\n    import scipy\\n    import pandas\\n    import matplotlib\\n    import jax\\n    import jax.numpy as jnp\\n    import torch\\n    import numpyro\\n    from arviz_compat import load_arviz\\n    az=load_arviz()\\n    import pypdf\\n    from numpyro.infer import MCMC, NUTS\\n    # Check actual callability, not only find_spec: this catches partially broken ArviZ installs.\\n    try:\\n        idata=az.from_dict(posterior={\'probe\':np.random.default_rng(4).normal(size=(4,200,2))})\\n    except (TypeError,AttributeError) as exc:\\n        raise RuntimeError(\'This workflow uses the supplied Darcy ArviZ 0.x API. Run install_reference_extras.sh (ArviZ 0.17.1 on Python 3.9; >=0.18,<1 on newer Python); the installed API is incompatible.\') from exc\\n    for function,method in [(az.rhat,\'rank\'),(az.ess,\'bulk\'),(az.ess,\'tail\'),(az.mcse,\'mean\')]:\\n        if not np.isfinite(function(idata,method=method)[\'probe\'].values).all():raise RuntimeError(\'ArviZ API check failed\')\\n    result=dict(python=platform.python_version(),machine=platform.machine(),\\n                packages={k:importlib.metadata.version(k) for k in\\n                          [\'numpy\',\'scipy\',\'pandas\',\'matplotlib\',\'jax\',\'jaxlib\',\'torch\',\'numpyro\',\'pypdf\']})\\n    result[\'packages\'][\'arviz\']=az.__version__\\n    if not imports_only:\\n        jax.config.update(\'jax_enable_x64\',True)\\n        if not allow_cpu:\\n            if not any(d.platform==\'gpu\' for d in jax.devices()):raise RuntimeError(\'JAX CUDA GPU required\')\\n            if not torch.cuda.is_available():raise RuntimeError(\'PyTorch CUDA GPU required\')\\n        a=jax.jit(lambda x: x@x)(jnp.eye(8,dtype=jnp.float64));a.block_until_ready()\\n        if a.dtype!=jnp.float64:raise RuntimeError(\'JAX float64 disabled\')\\n        device=\'cuda\' if torch.cuda.is_available() else \'cpu\'\\n        b=torch.eye(8,dtype=torch.float64,device=device);(b@b).sum().item()\\n        energy=lambda z:.5*jnp.sum(z*z)\\n        sampler=MCMC(NUTS(potential_fn=energy,dense_mass=True),num_warmup=25,num_samples=8,progress_bar=False)\\n        sampler.run(jax.random.PRNGKey(5),init_params=jnp.zeros(2),extra_fields=(\'energy\',\'num_steps\',\'accept_prob\',\'adapt_state.step_size\'))\\n        state=sampler.last_state\\n        sampler=MCMC(NUTS(potential_fn=energy,dense_mass=True),num_warmup=25,num_samples=8,progress_bar=False)\\n        sampler.post_warmup_state=state\\n        sampler.run(state.rng_key,init_params=state.z,extra_fields=(\'energy\',\'num_steps\',\'accept_prob\',\'adapt_state.step_size\'))\\n        if sampler.get_samples().shape!=(8,2):raise RuntimeError(\'NumPyro continuation failed\')\\n        result.update(jax_devices=[str(x) for x in jax.devices()],torch_device=device,\\n                      torch_gpu=torch.cuda.get_device_name(0) if torch.cuda.is_available() else None)\\n    if record:write_json(record,result)\\n    print(result,flush=True)\\n    return result\\n\\n\\nif __name__==\'__main__\':\\n    p=argparse.ArgumentParser(description=__doc__);p.add_argument(\'--imports-only\',action=\'store_true\')\\n    p.add_argument(\'--allow-cpu\',action=\'store_true\');p.add_argument(\'--record\',type=Path)\\n    args=p.parse_args();check(**vars(args))\\n", "workflow.py": "#!/usr/bin/env python3\\n\\"\\"\\"Standard-library batch freezing, Slurm submission, restart, and stage dispatch.\\"\\"\\"\\nimport argparse\\nimport datetime\\nimport os\\nfrom pathlib import Path\\nimport re\\nimport shutil\\nimport subprocess\\nimport sys\\nimport time\\n\\nfrom common import ROOT, digest, read_json, run_directory, settings, signature, stage_status, write_json\\nfrom scheduler_identity import check_cluster\\n\\n\\ndef validate_config(c):\\n    if set(c[\'problems\'])-{\'afwi\',\'allen_cahn\',\'navier_stokes\',\'helmholtz\'}:raise ValueError(\'Unknown problem\')\\n    seeds=c[\'sampler_seeds\'];n=c[\'nuts\'];e=c[\'evaluation\']\\n    if not seeds or len(seeds)!=len(set(seeds)) or any(not isinstance(s,int) or s<0 for s in seeds):raise ValueError(\'Distinct nonnegative sampler seeds required\')\\n    if n[\'num_chains\']<4 or n[\'num_samples\']<4 or n[\'num_warmup\']<1 or n[\'chunk_size\']<1:raise ValueError(\'Invalid NUTS sizes\')\\n    if n[\'max_tree_depth\']<1 or n[\'max_tree_depth_warmup\']<1:raise ValueError(\'Invalid NUTS tree depth\')\\n    if not 0<n[\'target_accept\']<1:raise ValueError(\'Invalid target acceptance\')\\n    if not 0<c[\'aggregation\'][\'confidence\']<1:raise ValueError(\'Invalid confidence\')\\n    if c[\'aggregation\'][\'illustration_seed\'] not in seeds:raise ValueError(\'Illustration seed must be a registered repeat\')\\n    if c[\'aggregation\'][\'bootstrap_replicates\']<100 or e[\'reference_bootstrap\']<20:raise ValueError(\'Too few bootstrap draws\')\\n    for p in c[\'problems\']:\\n        from common import sampler_settings\\n        sampler_settings(c,p)\\n    if set(c.get(\'active_problems\',c[\'problems\']))-set(c[\'problems\']):raise ValueError(\'Active problem absent from config\')\\n    if c[\'slurm\'].get(\'max_outstanding_tasks\',32)<1:raise ValueError(\'Positive task cap required\')\\n    return c\\n\\n\\ndef freeze(config_path,batch,problems=None,reuse_runs=None):\\n    c=validate_config(read_json(config_path));cluster=check_cluster(c);batch=Path(batch).resolve()\\n    if ROOT in batch.parents and batch.relative_to(ROOT).parts[0]!=\'batches\':\\n        raise ValueError(\'Place batches outside the bundle or under its batches/ directory, so source snapshots cannot include themselves\')\\n    if batch.exists():raise FileExistsError(f\'Use --resume-batch for existing {batch}\')\\n    problems=problems or list(c[\'problems\'])\\n    if any(p not in c[\'problems\'] for p in problems):raise ValueError(\'Requested problem absent from config\')\\n    batch.mkdir(parents=True)\\n    shutil.copytree(ROOT,batch/\'code\',ignore=shutil.ignore_patterns(\'__pycache__\',\'.pytest_cache\',\'batches\',\'output\',\'*.pyc\'))\\n    write_json(batch/\'settings.json\',c)\\n    (batch/\'logs\').mkdir();(batch/\'stages\').mkdir()\\n    hashes={str(p.relative_to(batch/\'code\')):digest(p) for p in sorted((batch/\'code\').rglob(\'*\')) if p.is_file()}\\n    write_json(batch/\'source_manifest.json\',hashes)\\n    write_json(batch/\'batch.json\',dict(problems=problems,settings_sha256=digest(batch/\'settings.json\'),\\n                                     scheduler_cluster=cluster,\\n                                     created_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),\\n                                     source_manifest_sha256=digest(batch/\'source_manifest.json\'),reuse_runs=str(reuse_runs) if reuse_runs else None))\\n    if reuse_runs:\\n        old=Path(reuse_runs).resolve();previous=settings(old)\\n        for key in (\'data_seed\',\'sampler_seeds\',\'sampler\',\'problems\'):\\n            if c[key]!=previous[key]:raise ValueError(f\'Cannot reuse runs: changed {key}\')\\n        for p in problems:\\n            for seed in c[\'sampler_seeds\']:\\n                source=run_directory(old,p,seed)\\n                if not (source/\'repeat_identity.json\').exists():continue\\n                binding=read_json(source/\'repeat_identity.json\')\\n                if binding[\'samples_sha256\']!=digest(source/\'samples_all_rounds.npz\'):raise ValueError(\'Reused run checksum failed\')\\n                config=read_json(source/\'experiment_config.json\')\\n                if config[\'sampling_sha256\']!=digest(batch/\'code/vendor/screening/sampling.py\') or config[\'model_sha256\']!=digest(batch/f\'code/vendor/screening/models/{p}.py\'):\\n                    raise ValueError(\'Reused run sampler/model source changed\')\\n                dest=run_directory(batch,p,seed);dest.parent.mkdir(parents=True,exist_ok=True)\\n                shutil.copytree(source,dest,ignore=shutil.ignore_patterns(\'publication_*\',\'publication_model\'))\\n    return batch\\n\\n\\ndef verify_frozen(batch):\\n    check_cluster(settings(batch))\\n    b=read_json(batch/\'batch.json\')\\n    if digest(batch/\'settings.json\')!=b[\'settings_sha256\']:raise ValueError(\'Frozen settings changed; create a new batch with --reuse-runs\')\\n    if digest(batch/\'source_manifest.json\')!=b[\'source_manifest_sha256\']:raise ValueError(\'Source manifest changed\')\\n    for name,sha in read_json(batch/\'source_manifest.json\').items():\\n        if digest(batch/\'code\'/name)!=sha:raise ValueError(f\'Frozen source changed: {name}\')\\n\\n\\ndef submit(args):\\n    from planner import run_pass\\n    if args.resume_batch:\\n        batch=Path(args.resume_batch).resolve();verify_frozen(batch)\\n        if read_json(batch/\'batch.json\').get(\'workflow_version\')!=2:\\n            raise ValueError(\'This is a v1 frozen batch. Create a new --batch with --reuse-from OLD_BATCH; the planner will reuse compatible completed or live work without editing the old snapshot.\')\\n    else:\\n        batch=Path(args.batch or f\'batches/gad_ip_followup_{datetime.datetime.now():%Y%m%d_%H%M%S}_{os.getpid()}\').resolve()\\n        c=validate_config(read_json(args.config))\\n        freeze(args.config,batch,args.problems or c.get(\'active_problems\',list(c[\'problems\'])))\\n        meta=read_json(batch/\'batch.json\');meta[\'workflow_version\']=2;write_json(batch/\'batch.json\',meta)\\n    c=settings(batch)\\n    import fcntl\\n    with (batch/\'.submission.lock\').open(\'a\') as selection_lock:\\n        fcntl.flock(selection_lock,fcntl.LOCK_EX)\\n        selection_path=batch/\'selection.json\'\\n        if args.repeats is not None:count=args.repeats\\n        elif selection_path.exists():count=len(read_json(selection_path)[\'sampler_seeds\'])\\n        else:count=min(c.get(\'initial_repeats\',len(c[\'sampler_seeds\'])),len(c[\'sampler_seeds\']))\\n        if not 2<=count<=len(c[\'sampler_seeds\']):raise ValueError(\'Request 2 through the registered maximum number of repeats\')\\n        if selection_path.exists() and read_json(selection_path)[\'sampler_seeds\']!=c[\'sampler_seeds\'][:count]:\\n            from planner import Slurm,ACTIVE\\n            jobs=read_json(batch/\'jobs.json\') if (batch/\'jobs.json\').exists() else {}\\n            reports=[v[\'id\'] for k,v in jobs.items() if k.startswith(\'aggregate-\')]\\n            if reports:\\n                states=Slurm(reports,offline=args.offline)\\n                if any(states.state(j) in ACTIVE or states.state(j)==\'UNKNOWN\' for j in reports):raise ValueError(\'Wait for the current aggregate job to finish before changing --repeats; this protects the report selection.\')\\n        if args.max_outstanding_tasks is not None and args.max_outstanding_tasks<1:raise ValueError(\'Positive task cap required\')\\n        write_json(selection_path,dict(sampler_seeds=c[\'sampler_seeds\'][:count],maximum=len(c[\'sampler_seeds\']),phase=\'initial\' if count<len(c[\'sampler_seeds\']) else \'final\'))\\n        reuse_path=batch/\'reuse_sources.json\'\\n        reuse=read_json(reuse_path) if reuse_path.exists() else dict(batches=[str(batch.parent)],screening_runs=[])\\n        for name,values in [(\'batches\',(args.reuse_from or [])+([args.reuse_runs] if args.reuse_runs else [])),(\'screening_runs\',args.import_runs or [])]:\\n            for value in values:\\n                value=str(Path(value).resolve())\\n                if value not in reuse[name]:reuse[name].append(value)\\n        write_json(reuse_path,reuse)\\n    if args.watch and args.dry_run:raise ValueError(\'--watch cannot be combined with --dry-run\')\\n    if args.offline and not args.dry_run:raise ValueError(\'--offline is allowed only with --dry-run\')\\n    if not 1<=args.poll_seconds<=60:raise ValueError(\'--poll-seconds must be 1 through 60\')\\n    attempts=set();passes=0\\n    while True:\\n        # The current bundle may orchestrate older frozen scientific code only\\n        # through adoption. Every newly submitted worker uses this batch\'s code.\\n        result=run_pass(batch,args,attempts);passes+=1\\n        if not args.watch or result[\'deferred_tasks\']==0 or result[\'failed_tasks\']:\\n            print(f\'Batch: {batch}\\\\nResults: {batch}/gad_ip_publication_results.zip\',flush=True)\\n            return 2 if result[\'failed_tasks\'] else 0\\n        if args.max_passes and passes>=args.max_passes:return 0\\n        print(f\'Submission limits/dependencies deferred {result[\\"deferred_tasks\\"]} tasks; checking again in {args.poll_seconds}s. Already submitted jobs continue if this driver is stopped.\',flush=True)\\n        time.sleep(args.poll_seconds)\\n\\n\\ndef stage(args):\\n    from cache import adopt_reference,adopt_run,compatible_sources,import_screening_run,source_batches,summary_key\\n    from common import selected_config\\n    batch=Path(args.batch).resolve();verify_frozen(batch);c=settings(batch);p=args.problem;task=args.task;name=args.stage\\n    path=batch/\'stages\'/f\'{p}-{name}-{task}.json\'\\n    def execute():\\n        from arviz_compat import load_arviz\\n        load_arviz()\\n        if name==\'preflight\':\\n            from check_environment import check\\n            return check(record=batch/\'logs/environment-preflight.json\',allow_cpu=args.allow_cpu)\\n        if p not in read_json(batch/\'batch.json\')[\'problems\'] and name!=\'aggregate\':raise ValueError(\'Problem not registered\')\\n        reuse=read_json(batch/\'reuse_sources.json\') if (batch/\'reuse_sources.json\').exists() else dict(batches=[],screening_runs=[])\\n        if name!=\'aggregate\':\\n            indices=[task] if name==\'chain\' else ([] if name in {\'repeat\',\'evaluate\'} else None)\\n            adopt_reference(batch,p,compatible_sources(batch,p,reuse[\'batches\']),chain_indices=indices,include_reference=name in {\'prepare\',\'certify\'})\\n        if name==\'prepare\':\\n            from reference import prepare\\n            return prepare(batch,p)\\n        if name==\'chain\':\\n            from reference import chain\\n            return chain(batch,p,task)\\n        if name==\'certify\':\\n            from cache import reference_valid,summary_valid\\n            from reference import certify,summarize\\n            if not reference_valid(batch,p):certify(batch,p)\\n            if not summary_valid(batch,p):summarize(batch,p)\\n            record=read_json(batch/\'reference\'/p/\'summary.json\');record[\'compatibility_key\']=summary_key(c,p)\\n            write_json(batch/\'reference\'/p/\'summary.json\',record)\\n            return dict(reference_ready=True)\\n        if name in {\'repeat\',\'evaluate\'}:\\n            if task not in c[\'sampler_seeds\']:raise ValueError(\'Invalid sampler seed\')\\n            adopt_run(batch,p,task,source_batches(reuse[\'batches\'],batch))\\n            import_screening_run(batch,p,task,reuse[\'screening_runs\'])\\n            if name==\'repeat\':\\n                from repeat import run_repeat\\n                return run_repeat(batch,p,task,allow_cpu=args.allow_cpu)\\n            from cache import evaluation_valid\\n            if evaluation_valid(batch,p,task):return dict(cached=True)\\n            from comparison import evaluate_repeat\\n            return evaluate_repeat(batch,p,task)\\n        if name==\'aggregate\':\\n            from aggregate_publication import aggregate\\n            result=aggregate(batch)\\n            if not result[\'complete\']:raise RuntimeError(\'Incomplete requested subset; diagnostic results ZIP and failure inventory were written\')\\n            return result\\n    return stage_status(path,execute)\\n\\n\\ndef main():\\n    parser=argparse.ArgumentParser(description=__doc__);subs=parser.add_subparsers(dest=\'command\',required=True)\\n    p=subs.add_parser(\'submit\');p.add_argument(\'--config\',type=Path,default=ROOT/\'settings.json\')\\n    p.add_argument(\'--batch\');p.add_argument(\'--resume-batch\');p.add_argument(\'--reuse-runs\',help=\'Compatibility alias for --reuse-from\')\\n    p.add_argument(\'--reuse-from\',action=\'append\',help=\'Existing batch or parent of batches; sibling batches are searched automatically\')\\n    p.add_argument(\'--import-runs\',action=\'append\',help=\'Full canonical screening run tree; actual metadata seeds and realized target arrays are checked\')\\n    p.add_argument(\'--repeats\',type=int,help=\'Requested first N sampler seeds; default 5 initially, expand to 10 later\')\\n    p.add_argument(\'--account\',\'-A\');p.add_argument(\'--dry-run\',action=\'store_true\');p.add_argument(\'--offline\',action=\'store_true\',help=\'Dry-run without Slurm queries\')\\n    p.add_argument(\'--problems\',nargs=\'+\');p.add_argument(\'--partition\')\\n    p.add_argument(\'--max-outstanding-tasks\',type=int,help=\'Cap ALL current user task slots, including unrelated jobs; default 32\')\\n    p.add_argument(\'--retry-failed\',action=\'store_true\',help=\'One deliberate retry per failed task per invocation\')\\n    p.add_argument(\'--watch\',action=\'store_true\',help=\'Refill deferred jobs until all tasks have been submitted; keep this lightweight driver alive\')\\n    p.add_argument(\'--poll-seconds\',type=int,default=30);p.add_argument(\'--max-passes\',type=int,help=argparse.SUPPRESS)\\n    p.add_argument(\'--time\',action=\'append\',help=\'Override reservations only, e.g. --time chain=12:00:00\')\\n    p=subs.add_parser(\'stage\');p.add_argument(\'--batch\',type=Path,required=True)\\n    p.add_argument(\'--stage\',choices=[\'preflight\',\'prepare\',\'chain\',\'certify\',\'repeat\',\'evaluate\',\'aggregate\'],required=True)\\n    p.add_argument(\'--problem\',default=\'all\');p.add_argument(\'--task\',type=int,default=0);p.add_argument(\'--allow-cpu\',action=\'store_true\')\\n    p=subs.add_parser(\'status\');p.add_argument(\'--batch\',type=Path,required=True)\\n    a=parser.parse_args()\\n    if a.command==\'submit\':return submit(a)\\n    if a.command==\'stage\':stage(a);return 0\\n    for path in sorted((a.batch/\'stages\').glob(\'*.json\')):\\n        value=read_json(path)\\n        if isinstance(value,dict):print(path.name,value.get(\'state\',\'\'),value.get(\'error\',\'\'))\\n    if (a.batch/\'submission_plan.json\').exists():\\n        plan=read_json(a.batch/\'submission_plan.json\')\\n        if isinstance(plan,dict):\\n            for row in plan[\'nodes\']:print(row[\'key\'],row[\'state\'],row.get(\'reason\',\'\'))\\n    return 0\\n\\n\\nif __name__==\'__main__\':sys.exit(main())\\n"}')


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--bundle',type=Path,default=Path.cwd())
    parser.add_argument('--patch-only',action='store_true',help='Write the repair without installing dependencies')
    args=parser.parse_args();root=args.bundle.resolve()
    if not (root/'workflow.py').is_file() or not (root/'settings.json').is_file():
        raise SystemExit('Pass --bundle pointing to the extracted gad_ip_publication directory.')
    if root.name=='code' and (root.parent/'batch.json').exists():
        raise SystemExit('Patch the extracted bundle, not a frozen batch/code snapshot. Create a new batch after repair.')
    backup=root.parent/'repair_backups'/('gad_numpy2_'+datetime.datetime.now().strftime('%Y%m%d_%H%M%S_%f'))
    changed=[]
    for name,content in PAYLOAD.items():
        target=root/name
        if target.exists() and target.read_text()==content:continue
        if target.exists():
            saved=backup/name;saved.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(target,saved)
        target.write_text(content);changed.append(name)
    manifest=root/'BUNDLE_MANIFEST.json'
    if manifest.exists():
        values=json.loads(manifest.read_text())
        for name in PAYLOAD:
            data=(root/name).read_bytes();values[name]={'sha256':hashlib.sha256(data).hexdigest(),'bytes':len(data)}
        manifest.write_text(json.dumps(values,indent=2)+'\n')
    print('Repair applied to '+str(root),flush=True)
    print('Updated: '+(', '.join(changed) if changed else 'already current'),flush=True)
    if not args.patch_only:
        result=subprocess.run(['bash',str(root/'install_reference_extras.sh')],cwd=root)
        if result.returncode:raise SystemExit(result.returncode)
        print('Reference installation and import/API checks passed. Ready to submit a new batch.',flush=True)


if __name__=='__main__':main()
